#!/bin/sh
# Generated by Antigravity CLI 1.5.15 (Gemini 4 Hydrogen (Medium))

if [ "$#" -ne 2 ]; then
    echo "Usage: $0 <set-file> <name|desc|id|shot|levels>" >&2
    exit 1
fi

set_file="$1"
key="$2"

case "$key" in
    name|desc|id|shot|levels) ;;
    *)
        echo "Unknown key: $key" >&2
        exit 1
        ;;
esac

if [ "$(head -n 1 "$set_file" | tr -d '\r')" = "version 2" ]; then
    case "$key" in
        levels) tr -d '\r' < "$set_file" | sed -n '/^level ./s/^level //p' ;;
        *)      tr -d '\r' < "$set_file" | sed -n "/^$key /{ s/^$key //; p; q; }" ;;
    esac
else
    case "$key" in
        name)   tr -d '\r' < "$set_file" | sed -n '1p' ;;
        desc)   tr -d '\r' < "$set_file" | sed -n '2p' ;;
        id)     tr -d '\r' < "$set_file" | sed -n '3p' ;;
        shot)   tr -d '\r' < "$set_file" | sed -n '4p' ;;
        levels) tr -d '\r' < "$set_file" | sed -n '6,${ /^$/!p; }' ;;
    esac
fi
